def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    colors = {}
    for row in g:
        for v in row:
            colors[v] = colors.get(v, 0) + 1
    bg = max(colors, key=colors.get)

    rows = [r for r in range(h) if all(v == 7 for v in g[r])]
    cols = [c for c in range(w) if all(g[r][c] == 7 for r in range(h))]

    if any(0 < r < h - 1 for r in rows):
        border = next(r for r in rows if 0 < r < h - 1)
        sides = [(0, border), (border + 1, h)]
        moving = 0 if sides[0][1] - sides[0][0] >= sides[1][1] - sides[1][0] else 1
        lo, hi = sides[moving]
        other_lo, other_hi = sides[1 - moving]
        cells = [(r, c) for r in range(lo, hi) for c in range(w)
                 if g[r][c] not in (bg, 7)]
        for r, c in cells:
            v = g[r][c]
            other = None
            for rr in range(other_lo, other_hi):
                if g[rr][c] not in (bg, 7):
                    other = g[rr][c]
                    break
            g[r][c] = bg
            if other == v:
                dest = border - 1 if moving == 0 else border + 1
            else:
                dest = lo if moving == 0 else hi - 1
            g[dest][c] = v
    else:
        border = next(c for c in cols if 0 < c < w - 1)
        sides = [(0, border), (border + 1, w)]
        moving = 0 if sides[0][1] - sides[0][0] >= sides[1][1] - sides[1][0] else 1
        lo, hi = sides[moving]
        other_lo, other_hi = sides[1 - moving]
        cells = [(r, c) for r in range(h) for c in range(lo, hi)
                 if g[r][c] not in (bg, 7)]
        for r, c in cells:
            v = g[r][c]
            other = None
            for cc in range(other_lo, other_hi):
                if g[r][cc] not in (bg, 7):
                    other = g[r][cc]
                    break
            g[r][c] = bg
            if other == v:
                dest = border - 1 if moving == 0 else border + 1
            else:
                dest = lo if moving == 0 else hi - 1
            g[r][dest] = v
    return g
